class TestLexicalAnalysis:
    def test_parse_entities_standard(self, engine):
        content = "User -> Auth : Login\nAuth -> DB : Query"
        nodes, edges = engine._parse_entities(content)
        
        assert len(nodes) == 3  # User, Auth, DB
        assert len(edges) == 2
        assert edges[0].source == "User"
        assert edges[0].target == "Auth"
        assert edges[0].label == "Login"

    def test_parse_entities_no_labels(self, engine):
        content = "A -> B\nB -> C"
        nodes, edges = engine._parse_entities(content)
        
        assert len(edges) == 2
        assert edges[0].label == ""
        assert edges[1].source == "B"

    def test_parse_entities_with_spaces(self, engine):
        content = "Auth Service -> User Database : Fetch Record"
        nodes, edges = engine._parse_entities(content)
        
        # IDs should be sanitized (spaces to underscores)
        assert nodes[0].id == "Auth_Service"
        assert edges[0].source == "Auth_Service"
        assert edges[0].target == "User_Database"
        assert edges[0].label == "Fetch Record"

