class TestStructuralValidation:
    def test_node_limit_exception(self, engine):
        # Create 101 nodes
        nodes = [Node(id=str(i), label=str(i)) for i in range(101)]
        edges = []
        with pytest.raises(DiagramSkillException) as excinfo:
            engine._validate_structure(nodes, edges)
        assert excinfo.value.code == "ERR_DSL_LIMIT"

    def test_cycle_detection_warning(self, engine, caplog):
        # Create a cycle: A -> B -> A
        nodes = [Node(id="A", label="A"), Node(id="B", label="B")]
        edges = [Edge(source="A", target="B"), Edge(source="B", target="A")]
        
        with caplog.at_level(logging.WARNING):
            engine._validate_structure(nodes, edges)
        
        assert "Circular reference detected: ERR_CIRCULAR_REF" in caplog.text

    def test_dag_no_warning(self, engine, caplog):
        # Directed Acyclic Graph: A -> B -> C
        nodes = [Node(id="A", label="A"), Node(id="B", label="B"), Node(id="C", label="C")]
        edges = [Edge(source="A", target="B"), Edge(source="B", target="C")]
        
        with caplog.at_level(logging.WARNING):
            engine._validate_structure(nodes, edges)
        
        assert "Circular reference detected" not in caplog.text

