class TestDSLGenerators:
    def test_mermaid_flowchart(self, engine):
        nodes = [Node("A", "A"), Node("B", "B")]
        edges = [Edge("A", "B", "Link")]
        s_map = SemanticMap(nodes, edges, DiagramType.FLOWCHART)
        theme = {"direction": "LR"}
        
        markup = engine._generators[TargetSyntax.MERMAID].generate(s_map, theme)
        assert "graph LR" in markup
        assert "A -->|Link| B" in markup

    def test_mermaid_sequence(self, engine):
        nodes = [Node("A", "A"), Node("B", "B")]
        edges = [Edge("A", "B", "Call")]
        s_map = SemanticMap(nodes, edges, DiagramType.SEQUENCE)
        
        markup = engine._generators[TargetSyntax.MERMAID].generate(s_map, {})
        assert "sequenceDiagram" in markup
        assert "A->>B: Call" in markup

    def test_plantuml_sequence(self, engine):
        nodes = [Node("A", "A"), Node("B", "B")]
        edges = [Edge("A", "B", "Call")]
        s_map = SemanticMap(nodes, edges, DiagramType.SEQUENCE)
        
        markup = engine._generators[TargetSyntax.PLANTUML].generate(s_map, {})
        assert "@startuml" in markup
        assert "A -> B : Call" in markup
        assert "@enduml" in markup

    def test_unsupported_mermaid_type(self, engine):
        nodes = [Node("A", "A")]
        edges = []
        s_map = SemanticMap(nodes, edges, DiagramType.ERD) # ERD not handled in MermaidGenerator
        
        markup = engine._generators[TargetSyntax.MERMAID].generate(s_map, {})
        assert "%% Unsupported Mermaid Type %%" in markup

