class TestDiagramSkillIntegration:
    def test_synthesize_success_mermaid_seq(self, engine, valid_sequence_input):
        result = engine.synthesize(
            source_content=valid_sequence_input,
            diagram_type=DiagramType.SEQUENCE,
            target_syntax=TargetSyntax.MERMAID,
            complexity=Complexity.HIGH
        )
        
        assert result.markup.startswith("sequenceDiagram")
        assert "Client->>Server: Request" in result.markup
        assert result.metadata["node_count"] == 3 # Client, Server, DB
        assert result.metadata["complexity"] == "HIGH"
        assert "artifact_id" in result.__dict__

    def test_synthesize_success_plantuml_flow(self, engine, valid_flowchart_input):
        result = engine.synthesize(
            source_content=valid_flowchart_input,
            diagram_type=DiagramType.FLOWCHART,
            target_syntax=TargetSyntax.PLANTUML
        )
        
        assert "@startuml" in result.markup
        assert "Start --> Process : Init" in result.markup
        assert result.metadata["edge_count"] == 2

    def test_synthesize_unsupported_syntax(self, engine, valid_sequence_input):
        # Mocking a syntax that isn't in the _generators map
        with patch.object(engine, '_generators', {}):
            with pytest.raises(DiagramSkillException) as excinfo:
                engine.synthesize(
                    source_content=valid_sequence_input,
                    diagram_type=DiagramType.SEQUENCE,
                    target_syntax=TargetSyntax.MERMAID
                )
            assert excinfo.value.code == "ERR_UNSUPPORTED_SYNTAX"

    def test_synthesize_empty_input(self, engine):
        result = engine.synthesize(
            source_content="",
            diagram_type=DiagramType.FLOWCHART,
            target_syntax=TargetSyntax.MERMAID
        )
        assert result.metadata["node_count"] == 0
        assert "graph TD" in result.markup # Default direction